<div class="flex flex-col gap-4 py-5">
<?php pl_ui_page_header(pl_t('Cash forecast'),pl_t('A simple cash scenario for {company}.', ['company' => $company['name']]),static function (): void { ?><span class="badge badge-info"><?= pl_e(pl_t('Planning scenario · Not actuals')) ?></span><a class="btn btn-ghost" href="<?= pl_e(pl_url('/reports')) ?>"><?= pl_e(pl_t('All reports')) ?></a><?php }); ?>
<?php if ($form['message']): ?><div class="alert alert-danger" role="alert" data-form-error><?= pl_e($form['message']) ?> <?= pl_e(pl_t('Your assumptions remain below.')) ?></div><?php endif; ?>
<div class="grid grid-cols-1 gap-4 lg:grid-cols-[320px_minmax(0,1fr)]"><form method="post" action="<?= pl_e(pl_url('/reports/cash-forecast')) ?>" class="rounded-panel border border-border bg-surface p-4 flex flex-col gap-3"><?= pl_csrf_field() ?><?= pl_scope_fields($company) ?><p class="eyebrow"><?= pl_e(pl_t('Your assumptions')) ?></p><h2 class="section-title"><?= pl_e(pl_t('What might change?')) ?></h2><p class="text-xs text-ink-muted"><?= pl_e(pl_t('Starting cash is {amount} from posted cash/bank accounts through {date}.', ['amount' => $company['currency'] . ' ' . pl_money($opening), 'date' => pl_date_label($asOf)])) ?></p><div class="flex flex-col gap-3"><label class="field"><?= pl_e(pl_t('Expected money in each week')) ?><input class="input" type="text" inputmode="decimal" name="weekly_in" value="<?= pl_e($input['weekly_in']) ?>" required pattern="[0-9]+(\.[0-9]{1,4})?"></label><label class="field"><?= pl_e(pl_t('Expected money out each week')) ?><input class="input" type="text" inputmode="decimal" name="weekly_out" value="<?= pl_e($input['weekly_out']) ?>" required pattern="[0-9]+(\.[0-9]{1,4})?"></label><label class="field"><?= pl_e(pl_t('Number of weeks')) ?><input class="input" type="number" name="weeks" min="1" max="52" value="<?= pl_e($input['weeks']) ?>" required></label></div><button type="submit" class="btn btn-primary justify-center"><?= pl_e(pl_t('Update scenario')) ?></button><p class="text-xs text-ink-muted"><?= pl_e(pl_t('Use decimal points without separators.')) ?> <?= pl_e($company['is_sample'] ? pl_t('The starting assumptions are illustrative sample amounts.') : pl_t('Enter your own assumptions; no automatic prediction is made.')) ?> <?= pl_e(pl_t('This does not post entries or change the books.')) ?></p></form>
<div><?php if ($forecast): ?><div class="rounded-panel border border-border bg-surface p-4 mb-3"><p class="eyebrow"><?= pl_e(pl_t('After {weeks} weeks', ['weeks' => (int) $forecast['weeks']])) ?></p><h2><?= pl_e($company['currency'] . ' ' . pl_money($forecast['closing'])) ?></h2><p><?= pl_e($forecast['first_negative_week'] !== null ? pl_t('This scenario first falls below zero in week {week}.', ['week' => (int) $forecast['first_negative_week']]) : pl_t('Cash stays at or above zero under these assumptions.')) ?></p></div><div class="rounded-panel border border-border bg-surface p-4 mb-3"><canvas hidden class="w-full h-auto" width="760" height="280" data-forecast-chart data-values="<?= pl_e(json_encode(array_merge([$forecast['opening']], array_column($forecast['rows'], 'closing')), JSON_THROW_ON_ERROR)) ?>" aria-label="<?= pl_e(pl_t('Scenario cash balance by week. Exact amounts appear in the table below.')) ?>" role="img"></canvas><noscript><p class="text-xs text-ink-muted"><?= pl_e(pl_t('The exact week-by-week scenario is available in the table below.')) ?></p></noscript></div><p class="text-xs text-ink-muted"><?= pl_e(pl_t('Opening cash + assumed inflows − assumed outflows. No receivables timing, seasonality, taxes or unrecorded commitments are automatically included.')) ?></p><?php else: ?><div class="empty-state"><h2><?= pl_e(pl_t('Adjust the assumptions to continue.')) ?></h2><p><?= pl_e(pl_t('The scenario will appear here when the values are valid.')) ?></p></div><?php endif; ?></div></div>
<?php if ($forecast): ?><details class="rounded-panel border border-border bg-surface p-4" open><summary><?= pl_e(pl_t('Week-by-week cash plan')) ?></summary><div class="table-wrap"><table class="table"><caption class="sr-only"><?= pl_e(pl_t('Scenario amounts in {currency}', ['currency' => $company['currency']])) ?></caption><thead><tr><th><?= pl_e(pl_t('Week')) ?></th><th class="amount"><?= pl_e(pl_t('Opening')) ?></th><th class="amount"><?= pl_e(pl_t('Money in')) ?></th><th class="amount"><?= pl_e(pl_t('Money out')) ?></th><th class="amount"><?= pl_e(pl_t('Closing')) ?></th></tr></thead><tbody><?php foreach ($forecast['rows'] as $row): ?><tr><th scope="row"><?= (int) $row['week'] ?></th><td class="amount"><?= pl_e(pl_money($row['opening'])) ?></td><td class="amount"><?= pl_e(pl_money($row['inflow'])) ?></td><td class="amount"><?= pl_e(pl_money($row['outflow'])) ?></td><td class="amount"><strong><?= pl_e(pl_money($row['closing'])) ?></strong></td></tr><?php endforeach; ?></tbody></table></div></details><?php endif; ?></div>
